import Image from "next/image";
import { cn } from "@/lib/utils";

export type ArtName = "hero" | "wide" | "deep" | "step1" | "step2" | "step3" | "cta";

/**
 * A panel of the painted green-to-orange artwork (public/art, generated by
 * scripts/art). Purely decorative: content placed inside sits on top, and
 * should go on `.glass` / `.glass-dark`, or be large white type with `scrim`.
 */
export function Art({
  name,
  className,
  ribbed = false,
  scrim = false,
  flip = false,
  priority = false,
  sizes = "(min-width: 1024px) 50vw, 100vw",
  children,
}: {
  name: ArtName;
  className?: string;
  /** Fluted-glass ribs over the paint. */
  ribbed?: boolean;
  /** Darken for white type set directly on the art. */
  scrim?: boolean;
  /** Turn the painting upside down (to put its green under white type). */
  flip?: boolean;
  priority?: boolean;
  sizes?: string;
  children?: React.ReactNode;
}) {
  return (
    <div className={cn("art", ribbed && "art--ribbed", scrim && "art--scrim", className)}>
      <Image
        src={`/art/${name}.webp`}
        alt=""
        fill
        sizes={sizes}
        priority={priority}
        className={cn("object-cover", flip && "rotate-180")}
      />
      {children}
    </div>
  );
}
